 static final class Row {String source,text="",background,foreground;RectF box;boolean heading;int proposedColor,colorVotes;Row(String s,RectF b,String bg,String fg,boolean h){source=s;box=b;background=bg;foreground=fg;heading=h;}}
 private static final class State {JSONObject card;List<Row> rows=new ArrayList<>();String candidate="",page="",rendered="";long lastPublish;long since,readAt,seen,generation,revision,retryAt;int failures;boolean busy,visible;final Set<String> failedPass=new HashSet<>();State(JSONObject c){card=c;}}
 private static final java.util.concurrent.atomic.AtomicLong REVISIONS=new java.util.concurrent.atomic.AtomicLong();
 private final Context context;private final Function<String,CompletableFuture<String>> translate;private final Consumer<JSONObject> output;
