 synchronized void reload(){List<State> updated=new ArrayList<>();JSONArray cards=ReadingCards.load(context);for(int i=0;i<cards.length();i++){JSONObject c=cards.optJSONObject(i);if(c==null||!c.optBoolean("enabled")||"dialogue".equals(c.optString("kind")))continue;State same=null;for(State old:states)if(old.card.optString("id").equals(c.optString("id"))&&old.card.toString().equals(c.toString())){same=old;break;}updated.add(same==null?new State(c):same);}for(State old:states)if(!updated.contains(old))clear(old);states.clear();states.addAll(updated);cursor=0;}
 void offer(Bitmap full){State selected=null;long now=SystemClock.elapsedRealtime();synchronized(this){if(closed||reader==null||states.isEmpty()||reading.get())return;for(State active:states)if("phone".equals(active.card.optString("kind"))&&active.seen>0&&now-active.seen<3000&&now-active.readAt>=active.card.optInt("intervalMs",450)){selected=active;break;}for(int i=0;selected==null&&i<states.size();i++){State s=states.get(cursor++%states.size());if(now-s.readAt>=s.card.optInt("intervalMs",450)){s.readAt=now;selected=s;break;}}}if(selected==null||!reading.compareAndSet(false,true))return;selected.readAt=now;State s=selected;Bitmap crop=null;
  try{float[] b=ReadingCards.bounds(s.card,"source");int x=Math.min(full.getWidth()-1,(int)(b[0]*full.getWidth())),y=Math.min(full.getHeight()-1,(int)(b[1]*full.getHeight()));crop=Bitmap.createBitmap(full,x,y,Math.max(1,Math.min(full.getWidth()-x,(int)(b[2]*full.getWidth()))),Math.max(1,Math.min(full.getHeight()-y,(int)(b[3]*full.getHeight()))));if(crop==full)crop=full.copy(Bitmap.Config.ARGB_8888,false);Bitmap image=crop;long generation=s.generation;
   reader.process(InputImage.fromBitmap(image,0)).addOnSuccessListener(result->{try{List<Row> rows=extract(result,image);accept(s,generation,rows);}finally{image.recycle();reading.set(false);}}).addOnFailureListener(error->{image.recycle();reading.set(false);});
  }catch(RuntimeException e){if(crop!=null&&crop!=full)crop.recycle();reading.set(false);}
 }
 static List<Row> extract(Text result,Bitmap image){List<Row> rows=new ArrayList<>();for(Text.TextBlock block:result.getTextBlocks())for(Text.Line line:block.getLines()){Rect r=line.getBoundingBox();String text=line.getText().trim();if(r==null||text.length()<2||text.length()>1500)continue;RectF box=new RectF(r.left/(float)image.getWidth(),r.top/(float)image.getHeight(),r.right/(float)image.getWidth(),r.bottom/(float)image.getHeight());int color=sample(image,r);int red=Color.red(color),g=Color.green(color),blue=Color.blue(color);String bg=String.format(Locale.ROOT,"#%06X",color&0xffffff),fg=(red*.299+g*.587+blue*.114)>155?"#20232A":"#FFFFFF";rows.add(new Row(text,box,bg,fg,false));}rows.sort(Comparator.comparingDouble(r->r.box.top));return rows.size()>64?new ArrayList<>(rows.subList(0,64)):rows;}
 private static int sample(Bitmap image,Rect r){int[] colors=new int[5];int[][] points={{r.left-4,r.centerY()},{r.right+4,r.centerY()},{r.centerX(),r.top-4},{r.centerX(),r.bottom+4},{r.left-4,r.top-4}};for(int i=0;i<5;i++)colors[i]=image.getPixel(Math.max(0,Math.min(image.getWidth()-1,points[i][0])),Math.max(0,Math.min(image.getHeight()-1,points[i][1])));Arrays.sort(colors);return colors[2];}
 static boolean dialogue(String s){return s.matches("(?is)^\\s*(?:[psefvic]\\s+)?(?:Jason|Lucia|Local|Locals|Tourists?|Stranger|Driver|Karim|Raul|Wade|Cop|Cops|Officer|Man|Woman)\\s*[:：].*");}
 static boolean control(String text){return text.trim().matches("(?i)(?:(?:EXIT|BACK|BICK|SELECT|SELEC|SELEI|PHOTO STUDIO|PHOTO MODE|SURFACE|O|X|LB|RB|LT|RT)(?:\\s+|$))+|[+\\s\\d.,]+\\s*(?:m|km|mi|ft)");}
 static boolean navigation(String text){String t=text.toUpperCase(Locale.ROOT);return t.contains("BRIEF")&&t.contains("PROGRESS")||t.contains("MAP")&&(t.contains("BRIEF")||t.contains("PROGRESS"));}
 static List<Row> groupRows(List<Row> source){List<Row> grouped=new ArrayList<>();for(Row row:source){Row previous=grouped.isEmpty()?null:grouped.get(grouped.size()-1);boolean same=false;try{int a=previous==null?0:Color.parseColor(previous.background),b=Color.parseColor(row.background);same=previous!=null&&Math.abs(Color.red(a)-Color.red(b))<35&&Math.abs(Color.green(a)-Color.green(b))<35&&Math.abs(Color.blue(a)-Color.blue(b))<35;}catch(IllegalArgumentException ignored){}if(previous!=null&&!previous.heading&&!row.heading&&same&&row.box.top>=previous.box.top&&row.box.top-previous.box.bottom<Math.min(previous.box.height(),row.box.height())*.45&&Math.min(previous.box.right,row.box.right)>Math.max(previous.box.left,row.box.left)){previous.source+=" "+row.source;previous.box.union(row.box);}else grouped.add(row);}return grouped;}
 private static int bubbleColor(String value){try{int c=Color.parseColor(value),r=Color.red(c),g=Color.green(c),b=Color.blue(c);return b>150&&g>75&&b-r>45?1:Math.min(r,Math.min(g,b))>125?2:0;}catch(IllegalArgumentException e){return 0;}}
 private static String key(String s){return s.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}
 private static boolean surface(Row row){try{int c=Color.parseColor(row.background);int r=Color.red(c),g=Color.green(c),b=Color.blue(c);return Math.min(r,Math.min(g,b))>125&&Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))<80||b>150&&g>75&&b-r>45;}catch(IllegalArgumentException e){return false;}}
 private synchronized void accept(State s,long generation,List<Row> found){if(closed||!states.contains(s)||s.generation!=generation)return;long now=SystemClock.elapsedRealtime();String kind=s.card.optString("kind");boolean phone="phone".equals(kind),message=phone||"notification".equals(kind);String all=String.join("\n",found.stream().map(r->r.source).toArray(String[]::new));
  if(message&&(navigation(all)||found.stream().anyMatch(r->dialogue(r.source)))){clear(s);return;}
  List<Row> rows=new ArrayList<>();for(Row r:found){if(control(r.source)||(!message&&dialogue(r.source)))continue;if(!message&&owned(r.box,ReadingCards.bounds(s.card,"source"),now))continue;rows.add(r);}
  if(phone){boolean body=rows.stream().anyMatch(r->r.source.trim().split("\\s+").length>=2||r.source.matches("(?s).*[!?].*"));float[] roi=ReadingCards.bounds(s.card,"source");boolean single=rows.size()==1&&roi[2]*roi[3]<=.2;
  if((rows.size()<2&&!single)||!body||rows.stream().filter(PhoneAreas::surface).count()<Math.max(1,rows.size()/2)){missing(s,now);return;}rows.get(0).heading=rows.get(0).box.top<.18&&rows.get(0).source.matches("[A-Z][A-Za-z'’-]+(?:[, ]+[A-Z][A-Za-z'’-]+){0,4}");rows=groupRows(rows);}
  if("map".equals(kind))rows.removeIf(r->{try{int color=Color.parseColor(r.background);return Math.max(Color.red(color),Math.max(Color.green(color),Color.blue(color)))>=110;}catch(IllegalArgumentException e){return true;}});
  if("map".equals(kind)&&rows.stream().noneMatch(r->r.source.matches(".*[a-z]{2,}.*")&&r.source.split("\\s+").length>=3)){missing(s,now);return;}
  if(rows.isEmpty()){missing(s,now);return;}
  String page=phone&&rows.get(0).heading?key(rows.get(0).source):"";if(!s.page.isEmpty()&&!page.isEmpty()&&!s.page.equals(page)){clear(s);}s.page=page;s.seen=now;
  if(phone)for(Row row:rows)for(Row old:s.rows){String a=key(row.source),b=key(old.source);boolean same=a.equals(b);boolean partial=Math.min(a.length(),b.length())>=12&&(a.startsWith(b)||b.startsWith(a))&&Math.min(a.split(" ").length,b.split(" ").length)>=3&&a.replaceAll("[^0-9]","").equals(b.replaceAll("[^0-9]",""))&&a.matches(".*\\b(?:not|no|never|don't|can't|won't)\\b.*")==b.matches(".*\\b(?:not|no|never|don't|can't|won't)\\b.*");if(same||partial){if(a.length()<b.length())row.source=old.source;int before=bubbleColor(old.background),after=bubbleColor(row.background);boolean adopt=false;if(before!=0&&after!=0&&before!=after){row.proposedColor=after;row.colorVotes=old.proposedColor==after?old.colorVotes+1:1;adopt=row.colorVotes>=2;}if(!adopt){row.background=old.background;row.foreground=old.foreground;}row.box=new RectF(old.box);break;}}
  String candidate=String.join("\n",rows.stream().map(r->r.source).toArray(String[]::new));if(!key(candidate).equals(key(s.candidate))){s.candidate=candidate;s.since=now;s.retryAt=0;s.failures=0;}s.rows=rows;
  for(Row r:rows)r.text=cache.getOrDefault(key(r.source),"");publish(s);if(phone)clearConflicts(now);
  if(!s.busy&&now-s.since>=120&&now>=s.retryAt){s.busy=true;s.failedPass.clear();translateNext(s,s.generation,0);}
 }
 private void missing(State s,long now){if(s.seen>0&&now-s.seen>=900)clear(s);}
 private synchronized boolean owned(RectF local,float[] source,long now){RectF absolute=new RectF(source[0]+local.left*source[2],source[1]+local.top*source[3],source[0]+local.right*source[2],source[1]+local.bottom*source[3]);for(State phone:states){if(!"phone".equals(phone.card.optString("kind"))||now-phone.seen>1800||phone.rows.isEmpty())continue;RectF bounds=new RectF(phone.rows.get(0).box);for(Row row:phone.rows)bounds.union(row.box);float[] p=ReadingCards.bounds(phone.card,"source");bounds.set(p[0]+bounds.left*p[2],p[1]+bounds.top*p[3],p[0]+bounds.right*p[2],p[1]+bounds.bottom*p[3]);RectF overlap=new RectF(absolute);if(overlap.intersect(bounds)&&overlap.width()*overlap.height()>=absolute.width()*absolute.height()*.5)return true;}return false;}
 private void clearConflicts(long now){for(State s:states){String kind=s.card.optString("kind");if(kind.equals("phone")||kind.equals("notification"))continue;if(s.rows.stream().anyMatch(r->owned(r.box,ReadingCards.bounds(s.card,"source"),now)))clear(s);}}
 private void translateNext(State s,long generation,int index){Row row;synchronized(this){if(closed||s.generation!=generation||!states.contains(s))return;if(index>=s.rows.size()){s.busy=false;boolean partial=s.rows.stream().anyMatch(r->r.text.isEmpty());if(partial){s.failures=Math.min(4,s.failures+1);s.retryAt=SystemClock.elapsedRealtime()+Math.min(8000,1000*(1<<(s.failures-1)));}return;}row=s.rows.get(index);if(!row.text.isEmpty()||s.failedPass.contains(key(row.source))){translateNext(s,generation,index+1);return;}}
  translate.apply(row.source).whenComplete((value,error)->{synchronized(PhoneAreas.this){if(closed||s.generation!=generation)return;if(error!=null)s.failedPass.add(key(row.source));if(error==null&&value!=null&&!value.trim().isEmpty()){if(cache.size()>=128)cache.clear();cache.put(key(row.source),value);for(Row current:s.rows)if(key(current.source).equals(key(row.source)))current.text=value;publish(s);}translateNext(s,generation,error==null?0:index+1);}});
 }
 private void publish(State s){if(s.rows.stream().noneMatch(r->!r.text.isEmpty()&&!r.heading))return;try{JSONArray cells=new JSONArray();String kind=s.card.optString("kind");boolean phone="phone".equals(kind)||"notification".equals(kind);int font=s.card.optInt("fontSize",28);double total=.04;for(Row r:s.rows)total+=Math.max(.065,Math.ceil(Math.max(r.source.length()*1.35,r.text.length())/27d)*.041+.025)+.025;final double extent=Math.max(1,total);double y=.02;for(Row r:s.rows){RectF b=r.box;if(phone){int lines=Math.max(1,(int)Math.ceil(Math.max(r.source.length()*1.35,r.text.length())/27d));double h=Math.max(.065,lines*.041+.025);double l=r.background.toUpperCase(Locale.ROOT).startsWith("#FFFFFF")?.03:.12;JSONObject box=ReadingCards.box(l,y/extent,.97,Math.min(.99,(y+h)/extent));cells.put(new JSONObject().put("source",r.source).put("text",r.text).put("box",box).put("background",r.background).put("foreground",r.foreground).put("lineHeight",.035/extent).put("bubble",!r.heading).put("heading",r.heading));y+=h+.025;}else cells.put(new JSONObject().put("source",r.source).put("text",r.text).put("box",ReadingCards.box(b.left,b.top,b.right,b.bottom)).put("background",r.background).put("foreground",r.foreground).put("lineHeight",Math.max(.02,b.height())));}
   JSONObject appearance=new JSONObject().put("font",s.card.optString("font","noto")).put("matchSize",false).put("phoneStyle",s.card.optString("phoneStyle","panel")).put("align","right").put("backdrop","source");JSONObject panel=new JSONObject().put("kind",phone?kind:"menu").put("width",400).put("height",phone?(int)Math.ceil(800*extent):400).put("cells",cells);String signature=panel.toString()+s.card.optJSONObject("output")+appearance.toString()+font+s.card.optInt("background",72);long now=SystemClock.elapsedRealtime();if(signature.equals(s.rendered)&&now-s.lastPublish<1100)return;s.rendered=signature;s.lastPublish=now;JSONObject value=new JSONObject().put("id",s.card.getString("id")).put("revision",REVISIONS.incrementAndGet()).put("text",s.candidate).put("duration",2200).put("output",s.card.getJSONObject("output")).put("fontSize",font).put("background",s.card.optInt("background",72)).put("appearance",appearance).put("panel",panel);s.visible=true;output.accept(value);
  }catch(JSONException ignored){}}
 private void clear(State s){s.generation++;s.rows.clear();s.candidate="";s.rendered="";s.busy=false;s.seen=0;if(s.visible){s.visible=false;try{output.accept(new JSONObject().put("id",s.card.optString("id")).put("revision",REVISIONS.incrementAndGet()).put("clear",true));}catch(JSONException ignored){}}}
 synchronized String dialogueText(Text result,int w,int h,float[] source){StringBuilder text=new StringBuilder();long now=SystemClock.elapsedRealtime();for(Text.TextBlock block:result.getTextBlocks())for(Text.Line line:block.getLines()){Rect b=line.getBoundingBox();if(b!=null&&!dialogue(line.getText())&&owned(new RectF(b.left/(float)w,b.top/(float)h,b.right/(float)w,b.bottom/(float)h),source,now))continue;if(text.length()>0)text.append('\n');text.append(line.getText());}return text.toString();}
